  1	/**
  2	 * Plans API Routes
  3	 *
  4	 * REST endpoints for plan operations:
  5	 * - GET /api/plans - list plans with status filter and task progress
  6	 * - GET /api/plans/:ref - get single plan with content
  7	 *
  8	 * AC Coverage:
  9	 * - @ui-plans-view ac-1: Plan list with title, status, dates, linked counts, progress
 10	 * - @ui-plans-view ac-2: Plan detail with content for expand/detail view
 11	 */
 12	
 13	import { Elysia, t } from 'elysia';
 14	import {
 15	  initContext,
 16	  loadPlans,
 17	  loadAllTasks,
 18	  findPlanByRef,
 19	  type LoadedPlan,
 20	} from '../../parser/index.js';
 21	import type { PlanSummary, PlanDetail } from '@kynetic-ai/shared';
 22	
 23	interface PlansRouteOptions {}
 24	
 25	/**
 26	 * Build a task status lookup map from loaded tasks.
 27	 */
 28	function buildTaskStatusMap(tasks: Array<{ _ulid: string; slugs: string[]; status: string }>) {
 29	  const tasksByRef = new Map<string, { status: string }>();
 30	  for (const task of tasks) {
 31	    tasksByRef.set(task._ulid, { status: task.status });
 32	    for (const slug of task.slugs) {
 33	      tasksByRef.set(slug, { status: task.status });
 34	    }
 35	  }
 36	  return tasksByRef;
 37	}
 38	
 39	/**
 40	 * Compute task progress for a plan's derived tasks.
 41	 */
 42	function computeTaskProgress(
 43	  derivedTasks: string[],
 44	  tasksByRef: Map<string, { status: string }>
 45	) {
 46	  const progress = { total: 0, completed: 0, in_progress: 0, pending: 0, blocked: 0 };
 47	  for (const ref of derivedTasks) {
 48	    const cleanRef = ref.startsWith('@') ? ref.slice(1) : ref;
 49	    const task = tasksByRef.get(cleanRef);
 50	    if (task) {
 51	      progress.total++;
 52	      if (task.status === 'completed') progress.completed++;
 53	      else if (task.status === 'in_progress' || task.status === 'pending_review' || task.status === 'needs_work') progress.in_progress++;
 54	      else if (task.status === 'blocked') progress.blocked++;
 55	      else progress.pending++;
 56	    }
 57	  }
 58	  return progress;
 59	}
 60	
 61	/**
 62	 * Map a loaded plan to a PlanSummary.
 63	 */
 64	function toPlanSummary(
 65	  plan: LoadedPlan,
 66	  tasksByRef: Map<string, { status: string }>
 67	): PlanSummary {
 68	  return {
 69	    _ulid: plan._ulid,
 70	    slugs: plan.slugs,
 71	    title: plan.title,
 72	    status: plan.status,
 73	    created_at: plan.created_at,
 74	    approved_at: plan.approved_at ?? undefined,
 75	    completed_at: plan.completed_at ?? undefined,
 76	    derived_specs: plan.derived_specs,
 77	    derived_tasks: plan.derived_tasks,
 78	    spec_count: plan.derived_specs.length,
 79	    task_count: plan.derived_tasks.length,
 80	    task_progress: computeTaskProgress(plan.derived_tasks, tasksByRef),
 81	  };
 82	}
 83	
 84	export function createPlansRoutes(options: PlansRouteOptions = {}) {
 85	  return new Elysia({ prefix: '/api/plans' })
 86	    // AC: @ui-plans-view ac-1 - List plans with progress
 87	    .get(
 88	      '/',
