  1	<!--
  2	  AC: @ui-plans-view ac-1 — Each plan shows title, status, creation date, linked spec/task counts, and progress.
  3	  AC: @ui-plans-view ac-2 — Expandable plan content rendered as formatted markdown, loaded on demand.
  4	-->
  5	<script lang="ts">
  6		import { onMount, onDestroy } from 'svelte';
  7		import { base } from '$app/paths';
  8		import type { PlanSummary } from '@kynetic-ai/shared';
  9		import { fetchPlans, fetchPlanContent } from '$lib/api';
 10		import { isStaticMode } from '$lib/stores/mode.svelte';
 11		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 12		import { getProjectVersion } from '$lib/stores/project.svelte';
 13		import { renderMarkdown } from '$lib/utils/markdown';
 14		import { Card, CardContent, CardHeader } from '$lib/components/ui/card';
 15		import { Badge } from '$lib/components/ui/badge';
 16		import { Button } from '$lib/components/ui/button';
 17		import { Skeleton } from '$lib/components/ui/skeleton';
 18		import MapIcon from '@lucide/svelte/icons/map';
 19		import FileTextIcon from '@lucide/svelte/icons/file-text';
 20		import ListTodoIcon from '@lucide/svelte/icons/list-todo';
 21		import ChevronDownIcon from '@lucide/svelte/icons/chevron-down';
 22	
 23		// ── Data state ──
 24		let plans = $state<PlanSummary[]>([]);
 25		let loading = $state(true);
 26		let error = $state('');
 27	
 28		// ── Filter state ──
 29		type PlanStatusFilter = 'all' | 'draft' | 'approved' | 'active' | 'completed' | 'rejected';
 30		let filterStatus = $state<PlanStatusFilter>('all');
 31	
 32		// ── Plan content expansion state ──
 33		// AC: @ui-plans-view ac-2 — Track expanded plans and their lazy-loaded content
 34		let expandedPlanId = $state<string | null>(null);
 35		let contentCache = $state<Record<string, string>>({});
 36		let contentLoading = $state<Record<string, boolean>>({});
 37		let contentError = $state<Record<string, string>>({});
 38	
 39		// ── Plan status labels and colors ──
 40		// AC: @ui-plans-view ac-1 — visually distinct statuses with text labels
 41		const PLAN_STATUS_LABELS: Record<string, string> = {
 42			draft: 'Draft',
 43			approved: 'Approved',
 44			active: 'Active',
 45			completed: 'Completed',
 46			rejected: 'Rejected'
 47		};
 48	
 49		const PLAN_STATUS_COLORS: Record<string, string> = {
 50			draft: 'bg-status-pending text-status-pending-fg',
 51			approved: 'bg-status-pending-review text-status-pending-review-fg',
 52			active: 'bg-status-in-progress text-status-in-progress-fg',
 53			completed: 'bg-status-completed text-status-completed-fg',
 54			rejected: 'bg-status-blocked text-status-blocked-fg'
 55		};
 56	
 57		// ── Filtered plans ──
 58		let filteredPlans = $derived.by(() => {
 59			if (filterStatus === 'all') return plans;
 60			return plans.filter((p) => p.status === filterStatus);
 61		});
 62	
 63		// ── Status summary counts ──
 64		let statusCounts = $derived.by(() => {
 65			const counts: Record<string, number> = {};
 66			for (const plan of plans) {
 67				counts[plan.status] = (counts[plan.status] ?? 0) + 1;
 68			}
 69			return counts;
 70		});
 71	
 72		// ── Lifecycle ──
 73		onMount(async () => {
 74			await loadData();
 75	
 76			if (!isStaticMode()) {
 77				// Plan progress is derived from task statuses, so subscribe to tasks:updates
 78				// to refresh when task status changes (e.g., task completed → plan progress updates)
 79				subscribe(['tasks:updates']);
 80				on('tasks:updates', handleUpdate);
 81			}
 82		});
 83	
 84		onDestroy(() => {
 85			if (!isStaticMode()) {
 86				off('tasks:updates', handleUpdate);
 87				unsubscribe(['tasks:updates']);
 88			}
 89		});
 90	
 91		// Reload on project change
 92		$effect(() => {
 93			const version = getProjectVersion();
 94			if (version > 0) {
 95				loadData();
 96			}
 97		});
 98	
 99		// ── Data loading ──
100		async function loadData() {
101			try {
102				loading = true;
103				error = '';
104				const response = await fetchPlans();
105				plans = response.items;
106			} catch (err) {
107				error = err instanceof Error ? err.message : 'Failed to load plans';
108			} finally {
109				loading = false;
110			}
111		}
112	
113		// ── WebSocket handler ──
114		function handleUpdate() {
115			loadData();
116		}
117	
118		// AC: @ui-plans-view ac-2 — Toggle plan content expansion, lazy-load content on first expand
119		async function togglePlanContent(plan: PlanSummary) {
120			const planRef = plan.slugs[0] ?? plan._ulid;
121	
122			if (expandedPlanId === plan._ulid) {
123				expandedPlanId = null;
124				return;
125			}
126	
127			expandedPlanId = plan._ulid;
128	
129			// Skip loading if already cached
130			if (contentCache[plan._ulid] !== undefined) return;
131	
132			// Don't re-fetch if already loading
133			if (contentLoading[plan._ulid]) return;
134	
135			contentLoading = { ...contentLoading, [plan._ulid]: true };
136			contentError = { ...contentError, [plan._ulid]: '' };
137	
138			try {
139				const detail = await fetchPlanContent(planRef);
140				contentCache = { ...contentCache, [plan._ulid]: detail.content };
141			} catch (err) {
142				contentError = {
143					...contentError,
144					[plan._ulid]: err instanceof Error ? err.message : 'Failed to load plan content'
145				};
146			} finally {
147				contentLoading = { ...contentLoading, [plan._ulid]: false };
148			}
149		}
150	
151		// ── Formatting ──
152		function formatDate(dateString: string): string {
153			const date = new Date(dateString);
154			const now = new Date();
155			const diffMs = now.getTime() - date.getTime();
156			const diffMins = Math.floor(diffMs / 60000);
157			const diffHours = Math.floor(diffMs / 3600000);
158			const diffDays = Math.floor(diffMs / 86400000);
159	
160			if (diffMins < 1) return 'just now';
161			if (diffMins < 60) return `${diffMins}m ago`;
162			if (diffHours < 24) return `${diffHours}h ago`;
163			if (diffDays < 7) return `${diffDays}d ago`;
164	
165			return date.toLocaleDateString();
166		}
167	
168		// AC: @ui-plans-view ac-1 — Progress percentage from task completion status
169		function progressPercent(plan: PlanSummary): number {
170			if (plan.task_progress.total === 0) return 0;
171			return Math.round((plan.task_progress.completed / plan.task_progress.total) * 100);
172		}
173	</script>
