  1	<!--
  2	  AC: @ui-plans-view ac-1 — Each plan shows title, status, creation date, linked spec/task counts, and progress.
  3	  AC: @ui-plans-view ac-2 — Expandable plan content rendered as formatted markdown, loaded on demand.
  4	-->
  5	<script lang="ts">
  6		import { onMount, onDestroy } from 'svelte';
  7		import { base } from '$app/paths';
  8		import type { PlanSummary } from '@kynetic-ai/shared';
  9		import { fetchPlans, fetchPlanContent } from '$lib/api';
 10		import { isStaticMode } from '$lib/stores/mode.svelte';
 11		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 12		import { getProjectVersion } from '$lib/stores/project.svelte';
 13		import { renderMarkdown } from '$lib/utils/markdown';
 14		import { Card, CardContent, CardHeader } from '$lib/components/ui/card';
 15		import { Badge } from '$lib/components/ui/badge';
 16		import { Button } from '$lib/components/ui/button';
